"""Working demo for this book record: full reader + HTML exporter.
Run:  python3 book_demo.py              (prints the whole book)
      python3 book_demo.py 3            (prints chapter 3 only)
      python3 book_demo.py search WORD  (finds WORD across chapters)
      python3 book_demo.py html         (writes book.html)
"""
import json, sys, html as _h

BOOK = {'title': 'The Mr. Big File', 'author': 'Signature original', 'genre': 'Cold Cases', 'chapters': [{'n': 1, 'title': 'The Client', 'text': "Sister Agnes whistled when they heard. 'Mr. Big is mixed up in this,' Sister Agnes said. 'You know what happened to the last shamus who crossed Mr. Big.' Frank Delaney knew. Everyone knew.\n\nThat night Frank Delaney stood at the office window, watching the neon bleed into the wet street. a bloodstained matchbook sat in the safe. Outside, the theater district did what it always did: it waited.\n\nFrank Delaney took the case. Not for the money — the money was insulting — but because a bloodstained matchbook had a look Frank Delaney recognized: the look of the one honest thing in a dirty town."}, {'n': 2, 'title': 'The Streets Talk', 'text': "Ruby sang the late set and slipped Frank Delaney a note between songs: a name, an address, a warning. 'They're watching you now,' she breathed. Frank Delaney tipped her and meant it.\n\nBack at the office, Frank Delaney spread the pieces out: a bloodstained matchbook, the ledger page, Ruby's note. The shape of it was Mr. Big, big as a building. And Frank Delaney was just one detective with a gun and a grudge against lies.\n\nSister Agnes drove the getaway when it went sour, which it did, because it always does. Bullets and rain on the windshield. Sister Agnes laughed the whole way. 'You owe me,' Sister Agnes said."}, {'n': 3, 'title': "The Dame's Story", 'text': "'Why should I trust you?' Frank Delaney asked. She had no answer that wasn't tears, and Frank Delaney had stopped buying tears during the war. But a bloodstained matchbook was real, and the ledger was real, and that was enough.\n\nSister Agnes didn't like it. 'Dames,' Sister Agnes said, 'are how detectives get killed.' Frank Delaney agreed and kept the case anyway. Some habits are stronger than sense.\n\nFrank Delaney took photographs with hands that didn't shake. Evidence. The one thing Mr. Big couldn't buy, beat, or bury. a bloodstained matchbook had led here, as a bloodstained matchbook always does, to the rotten center."}, {'n': 4, 'title': 'The Squeeze', 'text': "Sister Agnes showed up bloody and grinning. 'They hit like accountants,' Sister Agnes said. Frank Delaney felt the cold anger settle in, the kind that doesn't shout, just aims.\n\nFrank Delaney sat up all night with a bloodstained matchbook and the photographs and the whiskey going untouched. By dawn there was a plan. It wasn't a good plan. It was the only plan.\n\nRuby's club was next — a fire in the kitchen, a message in the smoke. Frank Delaney found her unharmed and furious, and that fury was worth ten guns. 'End this,' she said. Frank Delaney intended to."}, {'n': 5, 'title': 'The Confrontation', 'text': "It went down the way it always goes: shouting, threats, a gun that Frank Delaney was faster than. When the police took Mr. Big out, the theater district seemed to exhale, like a drunk finally telling the truth.\n\nThat night it rained again, washing the theater district clean for an hour. Frank Delaney stood at the window with a bloodstained matchbook — the case closed, the ledger in the DA's hands. redemption costs extra, Frank Delaney thought. Even here. Especially here.\n\nThe dame got her brother back and Frank Delaney got the rest of the fee, which was more than the insulting original. She cried. Frank Delaney didn't buy the tears but didn't charge for the shoulder, either."}, {'n': 6, 'title': 'Last Call', 'text': "a bloodstained matchbook went into the office safe, next to the other honest things. Someday, Frank Delaney knew, someone would walk in with something like it, and it would start again. It always starts again.\n\nThe phone rang. Frank Delaney picked it up. 'Frank Delaney Investigations,' Frank Delaney said, and listened, and smiled the thin smile of someone who knows exactly how much trouble costs. 'redemption costs extra. I'll take the case.'\n\nLou poured a double on the house. Ruby sang the song she only sings when she means it. Sister Agnes's ribs were taped, but Sister Agnes drank anyway, doctor's orders being for other people."}]}

def word_count():
    return sum(len(c["text"].split()) for c in BOOK["chapters"])

def print_book(ch=None):
    print("=" * 64)
    print(BOOK["title"].upper(), "\nby", BOOK["author"], "-", BOOK["genre"])
    print("=" * 64)
    for c in BOOK["chapters"]:
        if ch and c["n"] != ch:
            continue
        print("\n\nCHAPTER %d: %s\n%s" % (c["n"], c["title"], "-" * 40))
        print(c["text"])
    print("\n[%d words, %d chapters — complete]" % (word_count(), len(BOOK["chapters"])))

def search(word):
    w = word.lower()
    for c in BOOK["chapters"]:
        for i, para in enumerate(c["text"].split("\n\n")):
            if w in para.lower():
                print("[ch %d, para %d] %s..." % (c["n"], i + 1, para[:160].replace("\n", " ")))

def write_html(path="book.html"):
    parts = ["<html><head><meta charset='utf-8'><title>%s</title></head><body>" % _h.escape(BOOK["title"])]
    parts.append("<h1>%s</h1><p><i>by %s — %s</i></p>" % (_h.escape(BOOK["title"]), _h.escape(BOOK["author"]), _h.escape(BOOK["genre"])))
    for c in BOOK["chapters"]:
        parts.append("<h2>Chapter %d: %s</h2>" % (c["n"], _h.escape(c["title"])))
        for para in c["text"].split("\n\n"):
            parts.append("<p>%s</p>" % _h.escape(para))
    parts.append("</body></html>")
    open(path, "w").write("\n".join(parts))
    print("wrote", path)

if __name__ == "__main__":
    a = sys.argv[1:]
    if a and a[0] == "html":
        write_html()
    elif len(a) >= 2 and a[0] == "search":
        search(a[1])
    elif a and a[0].isdigit():
        print_book(int(a[0]))
    else:
        print_book()

